44|function globToRegExp(glob) {
45|  return new RegExp('^' + glob.split('*').map(escapeRegExp).join('.*') + '$');
46|}
47|
48|function escapeRegExp(text) {
49|  return text.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
50|}
51|
52|function basename(path) {
53|  const index = path.lastIndexOf('/');
54|  return index === -1 ? path : path.slice(index + 1);
55|}
56|
57|export function isIgnored(path) {
58|  const name = basename(path);
59|  for (const pattern of IGNORE_PATTERNS) {
60|    if (pattern.endsWith('/')) {
61|      if (path === pattern.slice(0, -1) || path.startsWith(pattern) || path.includes('/' + pattern)) {
62|        return true;
63|      }
64|    } else if (pattern.includes('*')) {
65|      if (globToRegExp(pattern).test(name)) return true;
66|    } else if (path === pattern || name === pattern || path.endsWith('/' + pattern)) {
67|      return true;
68|    }
69|  }
70|  return false;
71|}
72|
73|export function estimateTokens(bytes) {
74|  return Math.ceil(bytes / BYTES_PER_TOKEN);
75|}
76|
77|// Pure and testable: entries look like { path, bytes, isBinary }.
78|export function findOversized(entries) {
79|  const oversized = [];
80|  for (const entry of entries) {
81|    if (entry.isBinary || isIgnored(entry.path)) continue;
82|    const tokens = estimateTokens(entry.bytes);
83|    if (tokens > MAX_TOKENS) oversized.push({ path: entry.path, bytes: entry.bytes, tokens });
84|  }
85|  return oversized;
86|}
