98|function stagedPaths() {
99|  const output = execFileSync(
100|    'git',
101|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
102|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
103|  );
104|  const text = output.toString('utf8');
105|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
106|}
107|
108|// Binary flags from git's own numstat: git prints "-\t-\t" for files whose
109|// first 8000 bytes hold a NUL byte, so this reuses that detection.
110|function stagedBinaryFlags() {
111|  const output = execFileSync(
112|    'git',
113|    ['diff', '--cached', '--numstat', '--diff-filter=ACMR', '-z'],
114|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
115|  );
116|  const parts = output.toString('utf8').split('\0');
117|  const flags = new Map();
118|  for (let i = 0; i + 1 < parts.length; i += 2) {
119|    const counts = parts[i].split('\t');
120|    flags.set(parts[i + 1], counts[0] === '-' && counts[1] === '-');
121|  }
122|  return flags;
123|}
124|
125|function stagedBlobSize(path) {
126|  const output = execFileSync('git', ['cat-file', '-s', ':' + path], {
127|    encoding: 'utf8',
128|    stdio: ['ignore', 'pipe', 'ignore'],
129|  });
130|  return Number.parseInt(output.trim(), 10);
131|}
132|
133|function main() {
134|  let paths;
135|  let binaryFlags = new Map();
136|  try {
137|    paths = stagedPaths();
138|    binaryFlags = stagedBinaryFlags();
139|  } catch {
140|    console.error('warning: not a git repo, skipping the file-size check');
141|    return 0;
142|  }
143|  const entries = [];
144|  for (const path of paths) {
145|    if (isIgnored(path)) continue;
146|    let bytes;
147|    try {
148|      bytes = stagedBlobSize(path);
149|    } catch {
150|      continue; // Left the index since the diff was read.
151|    }
152|    entries.push({ path, bytes, isBinary: binaryFlags.get(path) === true });
153|  }
154|  const oversized = findOversized(entries);
155|  if (oversized.length === 0) return 0;
156|  console.error(`error: ${oversized.length} staged file(s) over the ${MAX_TOKENS}-token limit (tokens = ceil(bytes/4)):`);
157|  for (const file of oversized) {
158|    console.error(`  ${file.path}: ${file.bytes} bytes, about ${file.tokens} tokens`);
159|  }
160|  console.error('');
161|  console.error(SPLIT_HELP);
162|  return 1;
163|}
