1|// Pre-commit secret scan: staged text files must hold no credentials.
2|// With --all it scans every tracked file at HEAD plus full git history.
3|// Plain Node, no dependencies. Findings never print the secret itself.
4|import { execFileSync } from 'node:child_process';
5|import { fileURLToPath } from 'node:url';
6|import { isIgnored } from './check-file-size.mjs';
7|
8|export const ALLOW_MARKER = 'secret-scan:allow';
9|export const ENTROPY_THRESHOLD = 3.5;
10|export const ENTROPY_MIN_LENGTH = 20;
11|
12|// Each rule needs a token-looking suffix so prose that names a prefix
13|// (like this file) does not match. Keep it that way when adding rules.
14|export const RULES = [
15|  { name: 'jev', pattern: /\bjv_live_[A-Za-z0-9_-]{16,}/ },
16|  { name: 'openai', pattern: /sk-[A-Za-z0-9_-]{20,}/ },
17|  { name: 'meta-llm', pattern: /LLM\|[A-Za-z0-9_-]{10,}/ },
18|  { name: 'meta-bearer', pattern: /Bearer\s+[A-Za-z0-9._~-]{20,}/ },
19|  { name: 'github', pattern: /(?:ghp|gho)_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}/ },
20|  { name: 'aws', pattern: /AKIA[0-9A-Z]{16}/ },
21|  { name: 'private-key', pattern: /-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY-----/ },
22|  { name: 'redis-url', pattern: /rediss?:\/\/[^:\s]+:[^@\s]+@/ },
23|];
24|
25|const ASSIGNMENT = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/;
26|const SECRET_NAME = /(KEY|TOKEN|SECRET|PASSWORD)$/i;
27|const PLACEHOLDERS = ['your-', 'your_', 'changeme', 'change-me', 'xxx', '<', '>'];
28|
29|// File names refused whatever they hold. .env.example stays allowed.
30|export function isForbiddenFilename(path) {
31|  const slash = path.lastIndexOf('/');
32|  const name = slash === -1 ? path : path.slice(slash + 1);
33|  return (
34|    name === '.env' ||
35|    name === '.env.local' ||
36|    (name.startsWith('.env.') && name.endsWith('.local')) ||
37|    name.endsWith('.pem')
38|  );
39|}
40|
41|export function shannonEntropy(text) {
42|  const counts = new Map();
43|  for (const char of text) counts.set(char, (counts.get(char) ?? 0) + 1);
44|  let entropy = 0;
45|  for (const count of counts.values()) {
46|    const p = count / text.length;
47|    entropy -= p * Math.log2(p);
48|  }
49|  return entropy;
50|}
51|
52|function unquote(value) {
53|  if (value.length >= 2) {
54|    const first = value[0];
55|    const last = value[value.length - 1];
56|    if ((first === '"' || first === "'") && first === last) return value.slice(1, -1);
57|  }
58|  return value;
59|}
60|
61|function isPlaceholderValue(value) {
62|  const lower = value.toLowerCase();
63|  return PLACEHOLDERS.some((marker) => lower.includes(marker));
64|}
65|
66|export function redact(secret) {
67|  return secret.slice(0, 4) + '…';
68|}
69|
70|// Pure and testable: findings look like { path, line, rule, preview }.
71|export function scanContent(path, content) {
72|  const findings = [];
73|  const exampleFile = path === '.env.example' || path.endsWith('/.env.example');
74|  const lines = content.split('\n');
75|  for (let index = 0; index < lines.length; index++) {
76|    const line = lines[index];
77|    if (line.includes(ALLOW_MARKER)) continue;
78|    const assignment = ASSIGNMENT.exec(line);
79|    if (exampleFile && assignment) {
80|      const value = unquote(assignment[2]);
81|      if (value === '' || isPlaceholderValue(value)) continue;
82|    }
83|    for (const rule of RULES) {
84|      const match = rule.pattern.exec(line);
85|      if (match) {
86|        findings.push({ path, line: index + 1, rule: rule.name, preview: redact(match[0]) });
87|      }
88|    }
89|    if (assignment && SECRET_NAME.test(assignment[1])) {
90|      const value = unquote(assignment[2]);
91|      if (value.length >= ENTROPY_MIN_LENGTH && shannonEntropy(value) > ENTROPY_THRESHOLD) {
92|        findings.push({ path, line: index + 1, rule: 'high-entropy', preview: redact(value) });
93|      }
94|    }
95|  }
96|  return findings;
97|}
98|
99|export function isBinaryBuffer(buffer) {
100|  const head = buffer.subarray(0, 8000);
101|  return head.includes(0);
102|}
103|
104|function splitNul(output) {
105|  const text = output.toString('utf8');
106|  return text.length === 0 ? [] : text.split('\0').filter((entry) => entry !== '');
107|}
108|
109|function stagedPaths() {
110|  const output = execFileSync(
111|    'git',
112|    ['diff', '--cached', '--name-only', '--diff-filter=ACMR', '-z'],
113|    { encoding: 'buffer', stdio: ['ignore', 'pipe', 'ignore'] },
114|  );
115|  return splitNul(output);
116|}
117|
118|function headPaths() {
119|  const output = execFileSync('git', ['ls-tree', '-r', '--name-only', 'HEAD', '-z'], {
120|    encoding: 'buffer',
121|    stdio: ['ignore', 'pipe', 'ignore'],
122|  });
123|  return splitNul(output);
124|}
125|
126|function showBlob(revision, path) {
127|  return execFileSync('git', ['show', `${revision}:${path}`], {
128|    encoding: 'buffer',
129|    maxBuffer: 8 * 1024 * 1024,
130|    stdio: ['ignore', 'pipe', 'ignore'],
131|  });
132|}
133|
134|function scanBlob(revision, path, findings) {
135|  if (isForbiddenFilename(path)) {
136|    findings.push({ path, line: 0, rule: 'forbidden-filename', preview: '(blocked file name)' });
137|    return;
138|  }
139|  if (isIgnored(path)) return;
140|  let blob;
141|  try {
142|    blob = showBlob(revision, path);
143|  } catch {
144|    console.error(`warning: cannot read staged content of ${path}, skipping it`);
145|    return;
146|  }
147|  if (isBinaryBuffer(blob)) return;
148|  findings.push(...scanContent(path, blob.toString('utf8')));
149|}
150|
151|function scanHistory(findings) {
152|  let output;
153|  try {
154|    output = execFileSync('git', ['log', '-p', '--all'], {
155|      encoding: 'buffer',
156|      maxBuffer: 64 * 1024 * 1024,
157|      stdio: ['ignore', 'pipe', 'ignore'],
158|    });
159|  } catch {
160|    return; // No history yet.
161|  }
162|  let file = '<history>';
163|  for (const line of output.toString('utf8').split('\n')) {
164|    if (line.startsWith('+++ b/')) {
165|      file = line.slice('+++ b/'.length);
166|    } else if (line.startsWith('+') && !line.startsWith('+++')) {
167|      findings.push(...scanContent(`${file} (history)`, line.slice(1)));
168|    }
169|  }
170|}
171|
172|function report(findings) {
173|  if (findings.length === 0) return 0;
174|  console.error(`error: secret scan found ${findings.length} problem(s):`);
175|  for (const finding of findings) {
176|    const location = finding.line > 0 ? `${finding.path}:${finding.line}` : finding.path;
177|    console.error(`  ${location} [${finding.rule}] ${finding.preview}`);
178|  }
179|  console.error('Remove the secret (and any history that holds it), use an env var, then commit again.');
180|  return 1;
181|}
182|
183|function main() {
184|  const findings = [];
185|  if (process.argv.includes('--all')) {
186|    let paths;
187|    try {
188|      paths = headPaths();
189|    } catch {
190|      console.error('note: no commits yet, nothing to scan with --all');
191|      return 0;
192|    }
193|    for (const path of paths) scanBlob('HEAD', path, findings);
194|    scanHistory(findings);
195|    return report(findings);
196|  }
197|  let paths;
198|  try {
199|    paths = stagedPaths();
200|  } catch {
201|    console.error('warning: not a git repo, skipping the secret scan');
202|    return 0;
203|  }
204|  for (const path of paths) scanBlob('', path, findings);
205|  return report(findings);
206|}
207|
208|const invokedAsScript = process.argv[1] === fileURLToPath(import.meta.url);
209|if (invokedAsScript) process.exit(main());

