12|// Each rule needs a token-looking suffix so prose that names a prefix
13|// (like this file) does not match. Keep it that way when adding rules.
14|export const RULES = [
15|  { name: 'jev', pattern: /\bjv_live_[A-Za-z0-9_-]{16,}/ },
16|  { name: 'openai', pattern: /sk-[A-Za-z0-9_-]{20,}/ },
17|  { name: 'meta-llm', pattern: /LLM\|[A-Za-z0-9_-]{10,}/ },
18|  { name: 'meta-bearer', pattern: /Bearer\s+[A-Za-z0-9._~-]{20,}/ },
19|  { name: 'github', pattern: /(?:ghp|gho)_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}/ },
20|  { name: 'aws', pattern: /AKIA[0-9A-Z]{16}/ },
21|  { name: 'private-key', pattern: /-----BEGIN (?:[A-Z0-9]+ )*PRIVATE KEY-----/ },
22|  { name: 'redis-url', pattern: /rediss?:\/\/[^:\s]+:[^@\s]+@/ },
