25|const ASSIGNMENT = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/;
26|const SECRET_NAME = /(KEY|TOKEN|SECRET|PASSWORD)$/i;
27|const PLACEHOLDERS = ['your-', 'your_', 'changeme', 'change-me', 'xxx', '<', '>'];
28|
29|// File names refused whatever they hold. .env.example stays allowed.
30|export function isForbiddenFilename(path) {
31|  const slash = path.lastIndexOf('/');
32|  const name = slash === -1 ? path : path.slice(slash + 1);
33|  return (
34|    name === '.env' ||
35|    name === '.env.local' ||
36|    (name.startsWith('.env.') && name.endsWith('.local')) ||
37|    name.endsWith('.pem')
38|  );
39|}
