41|export function shannonEntropy(text) {
42|  const counts = new Map();
43|  for (const char of text) counts.set(char, (counts.get(char) ?? 0) + 1);
44|  let entropy = 0;
45|  for (const count of counts.values()) {
46|    const p = count / text.length;
47|    entropy -= p * Math.log2(p);
48|  }
49|  return entropy;
